package com.catcore.ctrlmietze.multitask;
import android.content.*; import java.io.*; import java.util.concurrent.*;
public final class TaskLauncher {
 private static final ExecutorService EXEC=Executors.newCachedThreadPool(); public interface Callback{void onResult(boolean ok,String msg);} private TaskLauncher(){}
 public static void launchNewTask(Context c,String pkg,String cls,Callback cb){ EXEC.execute(()->{ String comp=pkg+"/"+cls; String cmd="am start --user 0 --activity-new-task --activity-multiple-task --activity-new-document --activity-retain-in-recents -n "+q(comp); try{ Process p=new ProcessBuilder("su","-c",cmd).redirectErrorStream(true).start(); StringBuilder o=new StringBuilder(); try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()))){String line; while((line=r.readLine())!=null&&o.length()<1600)o.append(line).append('\n');} int code=p.waitFor(); if(code==0){post(c,cb,true,"Erfolgreich gestartet"); return;} post(c,cb,false,"Root-Start fehlgeschlagen: "+o.toString().trim()); }catch(Throwable e){ try{ Intent i=new Intent().setComponent(new ComponentName(pkg,cls)); i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK|Intent.FLAG_ACTIVITY_NEW_DOCUMENT|Intent.FLAG_ACTIVITY_RETAIN_IN_RECENTS); c.startActivity(i); post(c,cb,true,"Erfolgreich gestartet"); }catch(Throwable f){post(c,cb,false,"Start nicht möglich: "+f.getClass().getSimpleName());}} }); }
 private static void post(Context c,Callback cb,boolean ok,String m){if(cb!=null)new android.os.Handler(c.getMainLooper()).post(()->cb.onResult(ok,m));} private static String q(String s){return "'"+s.replace("'","'\''")+"'";}
}
